<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Assessment;use App\Models\AssessmentAssignment;use App\Models\JobApplication;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class AssessmentController extends Controller{public function companyIndex(Request $request):JsonResponse{$company=$this->company($request);return response()->json(['data'=>Assessment::where('company_id',$company->id)->latest()->get()]);}public function create(Request $request):JsonResponse{$company=$this->company($request);$data=$request->validate(['job_id'=>['nullable','integer'],'title'=>['required','string','max:150'],'instructions'=>['nullable','string','max:3000'],'duration_minutes'=>['required','integer','min:5','max:480'],'questions'=>['required','array','min:1','max:50'],'questions.*.prompt'=>['required','string','max:1000'],'questions.*.type'=>['required',Rule::in(['text','single_choice'])],'questions.*.options'=>['nullable','array'],'questions.*.correct_answer'=>['nullable','string','max:500']]);if(isset($data['job_id']))abort_unless($company->jobs()->whereKey($data['job_id'])->exists(),422);$assessment=Assessment::create([...$data,'company_id'=>$company->id,'created_by'=>$request->user()->id]);return response()->json(['data'=>$assessment,'message'=>'Prueba creada.'],201);}public function assign(Request $request,Assessment $assessment):JsonResponse{$company=$this->company($request);abort_unless($assessment->company_id===$company->id,404);$data=$request->validate(['application_id'=>['required','integer'],'due_at'=>['nullable','date','after:now']]);$application=JobApplication::whereKey($data['application_id'])->whereHas('job',fn($q)=>$q->where('company_id',$company->id))->firstOrFail();$assignment=AssessmentAssignment::firstOrCreate(['assessment_id'=>$assessment->id,'job_application_id'=>$application->id],['assigned_by'=>$request->user()->id,'due_at'=>$data['due_at']??null]);return response()->json(['data'=>$assignment,'message'=>'Prueba asignada.'],201);}public function candidateIndex(Request $request):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);return response()->json(['data'=>AssessmentAssignment::with('assessment:id,title,instructions,duration_minutes,questions','application.job:id,title')->whereHas('application',fn($q)=>$q->where('user_id',$request->user()->id))->latest()->get()]);}public function submit(Request $request,AssessmentAssignment $assignment):JsonResponse{abort_unless($assignment->application->user_id===$request->user()->id,404);abort_unless(in_array($assignment->status,['assigned','started']),422);abort_if($assignment->due_at&&$assignment->due_at->isPast(),422,'La prueba venció.');$data=$request->validate(['answers'=>['required','array']]);$questions=$assignment->assessment->questions;$correct=0;$graded=0;foreach($questions as $i=>$q){if(($q['type']??'')==='single_choice'&&isset($q['correct_answer'])){$graded++;if(($data['answers'][$i]??null)===$q['correct_answer'])$correct++;}}$score=$graded?round($correct/$graded*100,2):null;$assignment->update(['answers'=>$data['answers'],'score'=>$score,'status'=>'submitted','started_at'=>$assignment->started_at??now(),'submitted_at'=>now()]);return response()->json(['data'=>$assignment,'message'=>'Prueba entregada.']);}public function review(Request $request,AssessmentAssignment $assignment):JsonResponse{$company=$this->company($request);abort_unless($assignment->application->job->company_id===$company->id,404);$data=$request->validate(['score'=>['nullable','numeric','min:0','max:100'],'feedback'=>['nullable','string','max:3000']]);$assignment->update([...$data,'status'=>'reviewed']);return response()->json(['data'=>$assignment,'message'=>'Evaluación registrada.']);}public function evaluate(Request $request,JobApplication $application):JsonResponse{$company=$this->company($request);abort_unless($application->job->company_id===$company->id,404);$data=$request->validate(['ratings'=>['required','array'],'ratings.*'=>['integer','min:1','max:5'],'recommendation'=>['nullable','string','max:1000'],'private_comments'=>['nullable','string','max:3000']]);DB::table('application_evaluations')->updateOrInsert(['job_application_id'=>$application->id,'evaluator_id'=>$request->user()->id],['ratings'=>json_encode($data['ratings']),'recommendation'=>$data['recommendation']??null,'private_comments'=>$data['private_comments']??null,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Evaluación interna guardada.']);}private function company(Request $request){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;abort_unless(in_array($role,['owner','admin','recruiter']),403);return$company;}}
